const batch = [
  {
    minifigure_no: 'sw0623',
    name: 'Imperial Officer (Captain / Commandant / Commander) - Dark Tan Uniform',
    description_en: 'Imperial Officers in dark tan uniforms commanded various branches of the Imperial military including Army, Navy, and Stormtrooper Corps units. This minifigure\'s dark tan coloring represents the standard duty uniform worn by mid-ranking officers such as Captains, Commandants, and Commanders across Imperial installations. These officers were responsible for day-to-day operations, tactical decisions, and troop management on Star Destroyers, garrison worlds, and military facilities. The rank insignia plaques on their chest indicated their specific position within the complex Imperial hierarchy. Officers in this rank range served as the critical middle management linking Admiral commands with frontline troops. The dark tan uniform distinguishes these officers from higher-ranking admirals in white or olive uniforms. Collectors value this generic officer figure for building Imperial command structures and crew displays aboard Star Destroyers and Death Star recreations.',
    description_de: 'Imperiale Offiziere in dunklen beigen Uniformen befehligten verschiedene Zweige des imperialen Militärs einschließlich Armee-, Marine- und Sturmtruppenkorps-Einheiten. Die dunkle beige Färbung dieser Minifigur repräsentiert die Standard-Dienstuniform mittlerer Offiziere wie Hauptleute, Kommandanten und Kommandeure über imperiale Anlagen hinweg. Diese Offiziere waren für tägliche Operationen, taktische Entscheidungen und Truppenmanagement auf Sternenzerstörern, Garnisionswelten und Militäranlagen verantwortlich. Die Rangabzeichen-Plaketten auf ihrer Brust zeigten ihre spezifische Position innerhalb der komplexen imperialen Hierarchie an. Offiziere in diesem Rangbereich dienten als kritisches mittleres Management, das Admiralsbefehle mit Frontlinien-Truppen verband. Die dunkle beige Uniform unterscheidet diese Offiziere von höherrangigen Admirälen in weißen oder olivgrünen Uniformen. Sammler schätzen diese generische Offiziersfigur für den Aufbau imperialer Befehlsstrukturen und Crew-Displays an Bord von Sternenzerstörern und Todesstern-Nachstellungen.',
    description_fr: 'Les Officiers Impériaux en uniformes beige foncé commandaient diverses branches de l\'armée impériale incluant les unités de l\'Armée, de la Marine et du Corps des Stormtroopers. La coloration beige foncé de cette minifigurine représente l\'uniforme de service standard porté par les officiers de rang moyen tels que les Capitaines, Commandants et Commandeurs à travers les installations impériales. Ces officiers étaient responsables des opérations quotidiennes, des décisions tactiques et de la gestion des troupes sur les Destroyers Stellaires, les mondes de garnison et les installations militaires. Les plaques d\'insignes de rang sur leur poitrine indiquaient leur position spécifique dans la hiérarchie impériale complexe. Les officiers de cette gamme de rangs servaient de management intermédiaire critique reliant les commandes d\'Amiral aux troupes de première ligne. L\'uniforme beige foncé distingue ces officiers des amiraux de rang supérieur en uniformes blancs ou olive. Les collectionneurs apprécient cette figurine d\'officier générique pour construire des structures de commandement impériales et des displays d\'équipage à bord des Destroyers Stellaires et des recréations de l\'Étoile de la Mort.',
    description_es: 'Los Oficiales Imperiales con uniformes beige oscuro comandaban varias ramas del ejército imperial incluyendo unidades del Ejército, Marina y Cuerpo de Stormtroopers. La coloración beige oscuro de esta minifigura representa el uniforme de servicio estándar usado por oficiales de rango medio como Capitanes, Comandantes y Comandantes a través de instalaciones imperiales. Estos oficiales eran responsables de las operaciones diarias, decisiones tácticas y gestión de tropas en Destructores Estelares, mundos de guarnición e instalaciones militares. Las placas de insignias de rango en su pecho indicaban su posición específica dentro de la compleja jerarquía imperial. Los oficiales en este rango servían como gestión intermedia crítica conectando comandos de Almirantes con tropas de primera línea. El uniforme beige oscuro distingue a estos oficiales de almirantes de mayor rango en uniformes blancos u oliva. Los coleccionistas valoran esta figura de oficial genérico para construir estructuras de comando imperiales y exhibiciones de tripulación a bordo de Destructores Estelares y recreaciones de la Estrella de la Muerte.'
  },
  {
    minifigure_no: 'sw0624',
    name: 'AT-DP Pilot (Imperial Combat Driver - White Uniform)',
    description_en: 'AT-DP Pilots operated the All Terrain Defense Pod, a lightweight two-legged walker used by the Empire for urban patrol and garrison duty during the early Rebellion era. This minifigure features the distinctive white uniform of Imperial combat drivers, specialized for vehicle operation rather than infantry combat. The AT-DP was faster and more maneuverable than the larger AT-AT but less heavily armed, making it ideal for crowd control and city patrols on occupied worlds. These pilots appeared prominently in Star Wars Rebels hunting the Ghost crew through Lothal\'s streets and industrial areas. The white uniform with specialized helmet distinguished AT-DP pilots from gray-uniformed AT-ST and AT-AT drivers. Collectors value this figure for its connection to the Rebels series and for building Imperial occupation forces and walker displays that show the variety of Imperial ground vehicle operators beyond the classic AT-AT crews.',
    description_de: 'AT-DP-Piloten operierten den All Terrain Defense Pod, einen leichten zweibeinigen Läufer, der vom Imperium für Stadtpatrouillen und Garnisionsdienst während der frühen Rebellionsära eingesetzt wurde. Diese Minifigur zeigt die markante weiße Uniform imperialer Kampffahrer, spezialisiert für Fahrzeugbedienung anstatt Infanteriekampf. Der AT-DP war schneller und manövrierfähiger als der größere AT-AT, aber weniger schwer bewaffnet, was ihn ideal für Menschenkontrolle und Stadtpatrouillen auf besetzten Welten machte. Diese Piloten erschienen prominent in Star Wars Rebels bei der Jagd auf die Ghost-Crew durch Lothals Straßen und Industriegebiete. Die weiße Uniform mit spezialisiertem Helm unterschied AT-DP-Piloten von grau uniformierten AT-ST- und AT-AT-Fahrern. Sammler schätzen diese Figur für ihre Verbindung zur Rebels-Serie und für den Aufbau imperialer Besatzungstruppen und Läufer-Displays, die die Vielfalt imperialer Bodenfahrzeugoperatoren über die klassischen AT-AT-Crews hinaus zeigen.',
    description_fr: 'Les Pilotes d\'AT-DP opéraient le All Terrain Defense Pod, un marcheur bipède léger utilisé par l\'Empire pour les patrouilles urbaines et le service de garnison pendant l\'ère de la Rébellion précoce. Cette minifigurine présente l\'uniforme blanc distinctif des conducteurs de combat impériaux, spécialisés pour l\'opération de véhicules plutôt que le combat d\'infanterie. L\'AT-DP était plus rapide et plus maniable que le plus grand AT-AT mais moins lourdement armé, le rendant idéal pour le contrôle des foules et les patrouilles urbaines sur les mondes occupés. Ces pilotes sont apparus de manière proéminente dans Star Wars Rebels chassant l\'équipage du Ghost à travers les rues et zones industrielles de Lothal. L\'uniforme blanc avec casque spécialisé distinguait les pilotes d\'AT-DP des conducteurs d\'AT-ST et AT-AT en uniforme gris. Les collectionneurs apprécient cette figurine pour son lien avec la série Rebels et pour construire des forces d\'occupation impériales et des displays de marcheurs montrant la variété des opérateurs de véhicules terrestres impériaux au-delà des équipages classiques d\'AT-AT.',
    description_es: 'Los Pilotos de AT-DP operaban el All Terrain Defense Pod, un caminante bípedo ligero usado por el Imperio para patrullas urbanas y servicio de guarnición durante la era temprana de la Rebelión. Esta minifigura presenta el distintivo uniforme blanco de conductores de combate imperiales, especializados para operación de vehículos en lugar de combate de infantería. El AT-DP era más rápido y maniobrable que el AT-AT más grande pero menos armado pesadamente, haciéndolo ideal para control de multitudes y patrullas urbanas en mundos ocupados. Estos pilotos aparecieron prominentemente en Star Wars Rebels cazando a la tripulación del Ghost a través de las calles y áreas industriales de Lothal. El uniforme blanco con casco especializado distinguía a los pilotos de AT-DP de los conductores de AT-ST y AT-AT uniformados en gris. Los coleccionistas valoran esta figura por su conexión con la serie Rebels y para construir fuerzas de ocupación imperiales y exhibiciones de caminantes que muestran la variedad de operadores de vehículos terrestres imperiales más allá de las tripulaciones clásicas de AT-AT.'
  },
  {
    minifigure_no: 'sw0625',
    name: 'Agent Alexsandr Kallus - Helmet',
    description_en: 'Agent Alexsandr Kallus served as a high-ranking officer of the Imperial Security Bureau, hunting Rebel cells with ruthless efficiency before his eventual defection to the Rebellion. This minifigure features Kallus with his distinctive helmet worn during combat operations, representing his tactical gear used when personally leading stormtrooper squads. Kallus wielded a unique bo-rifle taken from a Lasat Honor Guard he defeated, making him a formidable hand-to-hand combatant. His character arc in Star Wars Rebels evolved from cold Imperial agent to Rebel spy codenamed Fulcrum, providing one of the series\' most compelling redemption stories. The helmeted version captures Kallus during his Imperial service before his transformation. Collectors appreciate this figure for its detailed uniform printing, connection to Kallus\' complex character development, and for displaying the ISB\'s role in hunting early Rebel cells across the galaxy.',
    description_de: 'Agent Alexsandr Kallus diente als hochrangiger Offizier des Kaiserlichen Sicherheitsbüros und jagte Rebellenzellen mit rücksichtsloser Effizienz, bevor er schließlich zur Rebellion überlief. Diese Minifigur zeigt Kallus mit seinem charakteristischen Helm, der während Kampfeinsätzen getragen wurde, und repräsentiert seine taktische Ausrüstung, die beim persönlichen Anführen von Sturmtruppler-Einheiten verwendet wurde. Kallus führte ein einzigartiges Bo-Gewehr, das er von einem Lasat-Ehrenwächter erbeutet hatte, was ihn zu einem formidablen Nahkämpfer machte. Sein Charakterbogen in Star Wars Rebels entwickelte sich vom kalten imperialen Agenten zum Rebellenspion mit dem Codenamen Fulcrum und lieferte eine der überzeugendsten Erlösungsgeschichten der Serie. Die behelmte Version erfasst Kallus während seines imperialen Dienstes vor seiner Transformation. Sammler schätzen diese Figur für ihre detaillierte Uniformbedruckung, Verbindung zu Kallus\' komplexer Charakterentwicklung und für die Darstellung der Rolle des ISB bei der Jagd auf frühe Rebellenzellen in der Galaxis.',
    description_fr: 'L\'Agent Alexsandr Kallus a servi comme officier de haut rang du Bureau de Sécurité Impérial, chassant les cellules rebelles avec une efficacité impitoyable avant sa défection éventuelle vers la Rébellion. Cette minifigurine présente Kallus avec son casque distinctif porté pendant les opérations de combat, représentant son équipement tactique utilisé lors de la direction personnelle d\'escouades de stormtroopers. Kallus maniait un fusil-bâton unique pris à un Garde d\'Honneur Lasat qu\'il avait vaincu, en faisant un combattant au corps à corps formidable. Son arc de personnage dans Star Wars Rebels a évolué d\'agent impérial froid à espion rebelle au nom de code Fulcrum, fournissant l\'une des histoires de rédemption les plus convaincantes de la série. La version casquée capture Kallus pendant son service impérial avant sa transformation. Les collectionneurs apprécient cette figurine pour son impression d\'uniforme détaillée, son lien avec le développement complexe du personnage de Kallus, et pour afficher le rôle de l\'ISB dans la chasse aux cellules rebelles précoces à travers la galaxie.',
    description_es: 'El Agente Alexsandr Kallus sirvió como oficial de alto rango del Buró de Seguridad Imperial, cazando células rebeldes con eficiencia despiadada antes de su eventual deserción a la Rebelión. Esta minifigura presenta a Kallus con su distintivo casco usado durante operaciones de combate, representando su equipo táctico usado al liderar personalmente escuadrones de stormtroopers. Kallus empuñaba un rifle-bastón único tomado de un Guardia de Honor Lasat que derrotó, convirtiéndolo en un formidable combatiente cuerpo a cuerpo. Su arco de personaje en Star Wars Rebels evolucionó de frío agente imperial a espía rebelde con nombre en clave Fulcrum, proporcionando una de las historias de redención más convincentes de la serie. La versión con casco captura a Kallus durante su servicio imperial antes de su transformación. Los coleccionistas aprecian esta figura por su impresión de uniforme detallada, conexión con el complejo desarrollo del personaje de Kallus, y para mostrar el papel del ISB en cazar células rebeldes tempranas a través de la galaxia.'
  },
  {
    minifigure_no: 'sw0626',
    name: 'Wullffwarro',
    description_en: 'Wullffwarro is a Wookiee warrior and father of Wullf Yularen who fought against Imperial occupation of Kashyyyk during the dark times following Order 66. This minifigure captures his distinctive appearance with detailed fur printing and warrior accessories representing his role in Wookiee resistance. After the Clone Wars ended, the Empire enslaved Wookiees for labor projects including Death Star construction, making warriors like Wullffwarro crucial leaders in liberation efforts. His appearance in Star Wars Rebels highlighted the Wookiees\' ongoing struggle against Imperial oppression. The detailed printing on this figure showcases LEGO\'s improved Wookiee designs with individual fur texture and tribal markings. Collectors value Wullffwarro for representing the Wookiee resistance movement and for displaying the personal stories of families torn apart by Imperial enslavement, making him essential for Kashyyyk and Rebellion displays.',
    description_de: 'Wullffwarro ist ein Wookiee-Krieger und Vater von Wullf Yularen, der gegen die imperiale Besetzung von Kashyyyk während der dunklen Zeiten nach Order 66 kämpfte. Diese Minifigur erfasst sein markantes Erscheinungsbild mit detaillierter Fellbedruckung und Krieger-Accessoires, die seine Rolle im Wookiee-Widerstand repräsentieren. Nach dem Ende der Klonkriege versklavte das Imperium Wookiees für Arbeitsprojekte einschließlich des Todesstern-Baus, was Krieger wie Wullffwarro zu entscheidenden Anführern in Befreiungsbemühungen machte. Sein Auftreten in Star Wars Rebels beleuchtete den anhaltenden Kampf der Wookiees gegen imperiale Unterdrückung. Die detaillierte Bedruckung dieser Figur zeigt LEGOs verbesserte Wookiee-Designs mit individueller Felltextur und Stammesmarkierungen. Sammler schätzen Wullffwarro für die Darstellung der Wookiee-Widerstandsbewegung und für die Darstellung der persönlichen Geschichten von Familien, die durch imperiale Versklavung auseinandergerissen wurden, was ihn unverzichtbar für Kashyyyk- und Rebellions-Displays macht.',
    description_fr: 'Wullffwarro est un guerrier Wookiee et père de Wullf Yularen qui a combattu l\'occupation impériale de Kashyyyk pendant les temps sombres suivant l\'Ordre 66. Cette minifigurine capture son apparence distinctive avec une impression de fourrure détaillée et des accessoires de guerrier représentant son rôle dans la résistance Wookiee. Après la fin de la Guerre des Clones, l\'Empire a réduit les Wookiees en esclavage pour des projets de travail incluant la construction de l\'Étoile de la Mort, rendant les guerriers comme Wullffwarro des leaders cruciaux dans les efforts de libération. Son apparition dans Star Wars Rebels a mis en lumière la lutte continue des Wookiees contre l\'oppression impériale. L\'impression détaillée de cette figurine met en valeur les designs Wookiee améliorés de LEGO avec texture de fourrure individuelle et marques tribales. Les collectionneurs apprécient Wullffwarro pour représenter le mouvement de résistance Wookiee et pour afficher les histoires personnelles de familles déchirées par l\'esclavage impérial, le rendant essentiel pour les displays de Kashyyyk et de la Rébellion.',
    description_es: 'Wullffwarro es un guerrero Wookiee y padre de Wullf Yularen que luchó contra la ocupación imperial de Kashyyyk durante los tiempos oscuros siguientes a la Orden 66. Esta minifigura captura su apariencia distintiva con impresión de pelaje detallada y accesorios de guerrero representando su papel en la resistencia Wookiee. Después de que terminaron las Guerras Clon, el Imperio esclavizó a los Wookiees para proyectos laborales incluyendo la construcción de la Estrella de la Muerte, haciendo que guerreros como Wullffwarro fueran líderes cruciales en esfuerzos de liberación. Su aparición en Star Wars Rebels destacó la lucha continua de los Wookiees contra la opresión imperial. La impresión detallada de esta figura muestra los diseños Wookiee mejorados de LEGO con textura de pelaje individual y marcas tribales. Los coleccionistas valoran a Wullffwarro por representar el movimiento de resistencia Wookiee y por mostrar las historias personales de familias desgarradas por la esclavitud imperial, haciéndolo esencial para exhibiciones de Kashyyyk y la Rebelión.'
  },
  {
    minifigure_no: 'sw0627',
    name: 'Wookiee - Reddish Brown with Dark Tan Fur, Printed Legs, Band on Left Arm',
    description_en: 'This Wookiee warrior features distinctive reddish brown coloring with dark tan fur patterns, printed legs showing traditional bandoliers and equipment, and a band on the left arm indicating clan affiliation or rank. Wookiees are known throughout the galaxy as fierce warriors, loyal companions, and skilled mechanics and pilots despite the Empire\'s attempts to enslave their species. The printed legs and arm band details represent LEGO\'s advancement in creating diverse Wookiee variants with individual characteristics. The reddish brown fur tone distinguishes this warrior from the more common brown Wookiees like Chewbacca, showing the natural diversity of Kashyyyk\'s population. Wookiees played crucial roles in both the Clone Wars fighting alongside Republic forces and in the Rebellion against Imperial oppression. Collectors value this variant for building diverse Wookiee forces, representing Kashyyyk\'s defenders, and creating Rebel Alliance displays that showcase the multi-species nature of the fight against the Empire.',
    description_de: 'Dieser Wookiee-Krieger zeigt markante rotbraune Färbung mit dunklen beigen Fellmustern, bedruckte Beine mit traditionellen Bandolieren und Ausrüstung sowie ein Band am linken Arm, das Clan-Zugehörigkeit oder Rang anzeigt. Wookiees sind in der gesamten Galaxis als wilde Krieger, loyale Gefährten und geschickte Mechaniker und Piloten bekannt, trotz der Versuche des Imperiums, ihre Spezies zu versklaven. Die bedruckten Beine und Armbanddetails repräsentieren LEGOs Fortschritt bei der Schaffung vielfältiger Wookiee-Varianten mit individuellen Merkmalen. Der rotbraune Fellton unterscheidet diesen Krieger von den häufigeren braunen Wookiees wie Chewbacca und zeigt die natürliche Vielfalt der Kashyyyk-Bevölkerung. Wookiees spielten entscheidende Rollen sowohl in den Klonkriegen an der Seite republikanischer Streitkräfte als auch in der Rebellion gegen imperiale Unterdrückung. Sammler schätzen diese Variante für den Aufbau vielfältiger Wookiee-Truppen, die Darstellung von Kashyyyks Verteidigern und die Erstellung von Rebellenallianz-Displays, die die multi-spezies Natur des Kampfes gegen das Imperium zeigen.',
    description_fr: 'Ce guerrier Wookiee présente une coloration brun rougeâtre distinctive avec des motifs de fourrure beige foncé, des jambes imprimées montrant des bandoulières traditionnelles et de l\'équipement, et un bandeau sur le bras gauche indiquant l\'affiliation clanique ou le rang. Les Wookiees sont connus à travers la galaxie comme de féroces guerriers, des compagnons loyaux et des mécaniciens et pilotes qualifiés malgré les tentatives de l\'Empire de réduire leur espèce en esclavage. Les détails des jambes imprimées et du bandeau de bras représentent l\'avancement de LEGO dans la création de variantes Wookiee diverses avec des caractéristiques individuelles. Le ton de fourrure brun rougeâtre distingue ce guerrier des Wookiees bruns plus courants comme Chewbacca, montrant la diversité naturelle de la population de Kashyyyk. Les Wookiees ont joué des rôles cruciaux à la fois dans la Guerre des Clones combattant aux côtés des forces de la République et dans la Rébellion contre l\'oppression impériale. Les collectionneurs apprécient cette variante pour construire des forces Wookiee diverses, représenter les défenseurs de Kashyyyk et créer des displays de l\'Alliance Rebelle qui mettent en valeur la nature multi-espèces de la lutte contre l\'Empire.',
    description_es: 'Este guerrero Wookiee presenta coloración marrón rojizo distintiva con patrones de pelaje beige oscuro, piernas impresas mostrando bandoleras tradicionales y equipo, y una banda en el brazo izquierdo indicando afiliación de clan o rango. Los Wookiees son conocidos a través de la galaxia como guerreros feroces, compañeros leales y mecánicos y pilotos hábiles a pesar de los intentos del Imperio de esclavizar a su especie. Las piernas impresas y detalles de banda de brazo representan el avance de LEGO en crear variantes Wookiee diversas con características individuales. El tono de pelaje marrón rojizo distingue a este guerrero de los Wookiees marrones más comunes como Chewbacca, mostrando la diversidad natural de la población de Kashyyyk. Los Wookiees jugaron papeles cruciales tanto en las Guerras Clon luchando junto a fuerzas de la República como en la Rebelión contra la opresión imperial. Los coleccionistas valoran esta variante para construir fuerzas Wookiee diversas, representar a los defensores de Kashyyyk y crear exhibiciones de la Alianza Rebelde que muestran la naturaleza multi-especies de la lucha contra el Imperio.'
  },
  {
    minifigure_no: 'sw0628',
    name: 'Gungan Warrior',
    description_en: 'Gungan Warriors formed the Grand Army of Boss Nass that defended Naboo against the Trade Federation\'s droid invasion in The Phantom Menace. This minifigure represents the amphibious soldiers of Naboo\'s underwater cities who emerged to fight in one of Star Wars\' largest ground battles. Gungan Warriors wielded distinctive weapons including energy balls called boomers, electropoles, and atlatl launchers, combined with massive energy shield technology. The Great Grass Plains battle showcased Gungan military tactics using shield generators and coordinated infantry assaults against overwhelming droid forces. Despite being dismissed as primitive by surface dwellers, Gungans proved their courage and tactical sophistication in defending their planet. The distinctive head shape with long ear stalks and tribal armor makes Gungan Warriors instantly recognizable. Collectors value these figures for building Grand Army displays, recreating the Battle of Naboo, and representing the alliance between Gungans and Naboo humans that saved their world.',
    description_de: 'Gungan-Krieger bildeten die Große Armee von Boss Nass, die Naboo gegen die Droideninvasion der Handelsföderation in Die dunkle Bedrohung verteidigte. Diese Minifigur repräsentiert die amphibischen Soldaten von Naboos Unterwasserstädten, die auftauchten, um in einer der größten Bodenschlachten von Star Wars zu kämpfen. Gungan-Krieger führten markante Waffen einschließlich Energiebälle namens Boomer, Elektrostangen und Atlatl-Werfer, kombiniert mit massiver Energieschildtechnologie. Die Schlacht auf den Großen Grasebenen zeigte Gungan-Militärtaktiken mit Schildgeneratoren und koordinierten Infanterieangriffen gegen überwältigende Droidenstreitkräfte. Obwohl sie von Oberflächenbewohnern als primitiv abgetan wurden, bewiesen Gungans ihren Mut und taktische Raffinesse bei der Verteidigung ihres Planeten. Die markante Kopfform mit langen Ohrstielen und Stammesrüstung macht Gungan-Krieger sofort erkennbar. Sammler schätzen diese Figuren für den Aufbau von Große-Armee-Displays, die Nachstellung der Schlacht um Naboo und die Darstellung der Allianz zwischen Gungans und Naboo-Menschen, die ihre Welt rettete.',
    description_fr: 'Les Guerriers Gungans formaient la Grande Armée de Boss Nass qui a défendu Naboo contre l\'invasion droïde de la Fédération du Commerce dans La Menace Fantôme. Cette minifigurine représente les soldats amphibies des cités sous-marines de Naboo qui ont émergé pour combattre dans l\'une des plus grandes batailles terrestres de Star Wars. Les Guerriers Gungans maniaient des armes distinctives incluant des balles d\'énergie appelées boomers, des électropoles et des lanceurs atlatl, combinées avec une technologie de bouclier énergétique massive. La bataille des Grandes Plaines Herbeuses a mis en valeur les tactiques militaires Gungans utilisant des générateurs de boucliers et des assauts d\'infanterie coordonnés contre des forces droïdes écrasantes. Bien qu\'étant considérés comme primitifs par les habitants de la surface, les Gungans ont prouvé leur courage et leur sophistication tactique en défendant leur planète. La forme de tête distinctive avec de longues tiges d\'oreilles et une armure tribale rend les Guerriers Gungans instantanément reconnaissables. Les collectionneurs apprécient ces figurines pour construire des displays de Grande Armée, recréer la Bataille de Naboo et représenter l\'alliance entre Gungans et humains de Naboo qui a sauvé leur monde.',
    description_es: 'Los Guerreros Gungan formaron el Gran Ejército de Boss Nass que defendió Naboo contra la invasión droide de la Federación de Comercio en La Amenaza Fantasma. Esta minifigura representa a los soldados anfibios de las ciudades submarinas de Naboo que emergieron para luchar en una de las batallas terrestres más grandes de Star Wars. Los Guerreros Gungan empuñaban armas distintivas incluyendo bolas de energía llamadas boomers, electropostes y lanzadores atlatl, combinadas con tecnología de escudo de energía masiva. La batalla de las Grandes Llanuras de Hierba mostró tácticas militares Gungan usando generadores de escudo y asaltos de infantería coordinados contra abrumadoras fuerzas droides. A pesar de ser descartados como primitivos por habitantes de superficie, los Gungans demostraron su coraje y sofisticación táctica al defender su planeta. La distintiva forma de cabeza con largos tallos de orejas y armadura tribal hace que los Guerreros Gungan sean instantáneamente reconocibles. Los coleccionistas valoran estas figuras para construir exhibiciones del Gran Ejército, recrear la Batalla de Naboo y representar la alianza entre Gungans y humanos de Naboo que salvó su mundo.'
  },
  {
    minifigure_no: 'sw0629',
    name: 'Clone Trooper Lieutenant (Phase 1) - Printed Legs, Scowl',
    description_en: 'Clone Trooper Lieutenants commanded platoon-sized units of approximately 36 clone troopers during the Clone Wars, serving as crucial mid-level officers in the Grand Army of the Republic. This Phase 1 variant features the characteristic blue markings that identified Lieutenant rank, printed legs showing full armor detail, and a scowling expression reflecting the intensity of Clone Wars combat. Phase 1 armor was worn during the early Clone Wars battles including Geonosis, Christophsis, and Teth. The blue color coding system helped Jedi generals and fellow clones quickly identify unit command structures on chaotic battlefields. Lieutenants served directly under Captains and above Sergeants, making tactical decisions during engagements. The printed legs represent LEGO\'s evolution toward more detailed clone trooper figures. Collectors value this lieutenant variant for building accurate Clone Wars command structures, creating color-coded legions, and displaying the Republic\'s military hierarchy during the early war period.',
    description_de: 'Klonkrieger-Leutnants befehligten Züge von etwa 36 Klonkriegern während der Klonkriege und dienten als entscheidende mittlere Offiziere in der Großen Armee der Republik. Diese Phase-1-Variante zeigt die charakteristischen blauen Markierungen, die den Leutnant-Rang identifizierten, bedruckte Beine mit vollständigem Rüstungsdetail und einen grimmigen Ausdruck, der die Intensität der Klonkriegs-Kämpfe widerspiegelt. Phase-1-Rüstung wurde während der frühen Klonkriegs-Schlachten einschließlich Geonosis, Christophsis und Teth getragen. Das blaue Farbcodierungssystem half Jedi-Generälen und Mitkollegen, Einheitenbefehlsstrukturen auf chaotischen Schlachtfeldern schnell zu identifizieren. Leutnants dienten direkt unter Hauptleuten und über Feldwebeln und trafen taktische Entscheidungen während Gefechten. Die bedruckten Beine repräsentieren LEGOs Entwicklung zu detaillierteren Klonkrieger-Figuren. Sammler schätzen diese Leutnant-Variante für den Aufbau genauer Klonkriegs-Befehlsstrukturen, die Erstellung farbcodierter Legionen und die Darstellung der militärischen Hierarchie der Republik während der frühen Kriegsperiode.',
    description_fr: 'Les Lieutenants Clone Trooper commandaient des unités de taille de peloton d\'environ 36 clone troopers pendant la Guerre des Clones, servant d\'officiers de niveau intermédiaire cruciaux dans la Grande Armée de la République. Cette variante de Phase 1 présente les marques bleues caractéristiques qui identifiaient le rang de Lieutenant, des jambes imprimées montrant les détails complets de l\'armure et une expression renfrognée reflétant l\'intensité des combats de la Guerre des Clones. L\'armure de Phase 1 était portée pendant les premières batailles de la Guerre des Clones incluant Geonosis, Christophsis et Teth. Le système de codage de couleur bleu aidait les généraux Jedi et les clones compagnons à identifier rapidement les structures de commandement d\'unité sur les champs de bataille chaotiques. Les Lieutenants servaient directement sous les Capitaines et au-dessus des Sergents, prenant des décisions tactiques pendant les engagements. Les jambes imprimées représentent l\'évolution de LEGO vers des figurines de clone trooper plus détaillées. Les collectionneurs apprécient cette variante de lieutenant pour construire des structures de commandement précises de la Guerre des Clones, créer des légions codées par couleur et afficher la hiérarchie militaire de la République pendant la période de guerre précoce.',
    description_es: 'Los Tenientes Clone Trooper comandaban unidades de tamaño pelotón de aproximadamente 36 clone troopers durante las Guerras Clon, sirviendo como oficiales de nivel medio cruciales en el Gran Ejército de la República. Esta variante de Fase 1 presenta las características marcas azules que identificaban el rango de Teniente, piernas impresas mostrando detalle completo de armadura y una expresión ceñuda reflejando la intensidad del combate de las Guerras Clon. La armadura de Fase 1 fue usada durante las primeras batallas de las Guerras Clon incluyendo Geonosis, Christophsis y Teth. El sistema de codificación de color azul ayudaba a generales Jedi y clones compañeros a identificar rápidamente estructuras de comando de unidad en campos de batalla caóticos. Los Tenientes servían directamente bajo Capitanes y sobre Sargentos, tomando decisiones tácticas durante enfrentamientos. Las piernas impresas representan la evolución de LEGO hacia figuras de clone trooper más detalladas. Los coleccionistas valoran esta variante de teniente para construir estructuras de comando precisas de las Guerras Clon, crear legiones codificadas por color y mostrar la jerarquía militar de la República durante el período de guerra temprano.'
  },
  {
    minifigure_no: 'sw0630',
    name: 'Imperial Stormtrooper Sergeant',
    description_en: 'Imperial Stormtrooper Sergeants commanded individual squads of approximately nine stormtroopers, representing the frontline leadership of the Empire\'s most visible military force. This minifigure features distinctive sergeant markings, likely including shoulder pauldrons or armor detailing that differentiated non-commissioned officers from standard troopers. Stormtrooper Sergeants were responsible for tactical execution of orders, squad discipline, and direct combat leadership during Imperial operations. The rank structure within stormtrooper units mirrored traditional military organization, with sergeants serving as the critical link between commanders and enlisted troops. These NCOs often led boarding parties, garrison patrols, and ground assault teams across the galaxy. The sergeant designation adds command variety to stormtrooper displays and reflects the Empire\'s rigid military hierarchy. Collectors value sergeant variants for building realistic Imperial squad compositions, showing rank diversity, and creating more authentic command structures in Death Star, Star Destroyer, and planetary garrison scenes.',
    description_de: 'Imperiale Sturmtruppler-Feldwebel befehligten einzelne Trupps von etwa neun Sturmtrupplern und repräsentierten die Frontlinien-Führung der sichtbarsten Militärmacht des Imperiums. Diese Minifigur zeigt markante Feldwebel-Markierungen, wahrscheinlich einschließlich Schulterschutz oder Rüstungsdetails, die Unteroffiziere von Standard-Soldaten unterschieden. Sturmtruppler-Feldwebel waren verantwortlich für taktische Ausführung von Befehlen, Truppdisziplin und direkte Kampfführung während imperialer Operationen. Die Rangstruktur innerhalb von Sturmtruppler-Einheiten spiegelte traditionelle militärische Organisation wider, wobei Feldwebel als kritisches Bindeglied zwischen Kommandeuren und einfachen Soldaten dienten. Diese Unteroffiziere führten oft Enterpartys, Garnisonspatrouillen und Bodenangriffsteams in der gesamten Galaxis an. Die Feldwebel-Bezeichnung fügt Befehlsvielfalt zu Sturmtruppler-Displays hinzu und spiegelt die starre militärische Hierarchie des Imperiums wider. Sammler schätzen Feldwebel-Varianten für den Aufbau realistischer imperialer Truppzusammensetzungen, die Darstellung von Rangvielfalt und die Erstellung authentischerer Befehlsstrukturen in Todesstern-, Sternenzerstörer- und planetaren Garnisonsszenen.',
    description_fr: 'Les Sergents Stormtrooper Impériaux commandaient des escouades individuelles d\'environ neuf stormtroopers, représentant le leadership de première ligne de la force militaire la plus visible de l\'Empire. Cette minifigurine présente des marques de sergent distinctives, incluant probablement des épaulières ou des détails d\'armure qui différenciaient les sous-officiers des soldats standard. Les Sergents Stormtrooper étaient responsables de l\'exécution tactique des ordres, de la discipline de l\'escouade et du leadership de combat direct pendant les opérations impériales. La structure de rang au sein des unités de stormtroopers reflétait l\'organisation militaire traditionnelle, les sergents servant de lien critique entre les commandants et les troupes enrôlées. Ces sous-officiers menaient souvent des équipes d\'abordage, des patrouilles de garnison et des équipes d\'assaut au sol à travers la galaxie. La désignation de sergent ajoute une variété de commandement aux displays de stormtroopers et reflète la hiérarchie militaire rigide de l\'Empire. Les collectionneurs apprécient les variantes de sergent pour construire des compositions d\'escouade impériale réalistes, montrer la diversité des rangs et créer des structures de commandement plus authentiques dans les scènes de l\'Étoile de la Mort, du Destroyer Stellaire et de garnison planétaire.',
    description_es: 'Los Sargentos Stormtrooper Imperiales comandaban escuadrones individuales de aproximadamente nueve stormtroopers, representando el liderazgo de primera línea de la fuerza militar más visible del Imperio. Esta minifigura presenta marcas distintivas de sargento, probablemente incluyendo hombreras o detalle de armadura que diferenciaba a los suboficiales de los soldados estándar. Los Sargentos Stormtrooper eran responsables de la ejecución táctica de órdenes, disciplina de escuadrón y liderazgo de combate directo durante operaciones imperiales. La estructura de rango dentro de unidades de stormtroopers reflejaba la organización militar tradicional, con sargentos sirviendo como enlace crítico entre comandantes y tropas alistadas. Estos suboficiales a menudo lideraban partidas de abordaje, patrullas de guarnición y equipos de asalto terrestre a través de la galaxia. La designación de sargento añade variedad de comando a exhibiciones de stormtroopers y refleja la rígida jerarquía militar del Imperio. Los coleccionistas valoran variantes de sargento para construir composiciones de escuadrón imperial realistas, mostrar diversidad de rangos y crear estructuras de comando más auténticas en escenas de Estrella de la Muerte, Destructor Estelar y guarnición planetaria.'
  },
  {
    minifigure_no: 'sw0631',
    name: 'Boba Fett - White, Detailed Pattern',
    description_en: 'This unique white Boba Fett variant represents either prototype Mandalorian armor, early career designs, or specialized winter camouflage gear used by the galaxy\'s most famous bounty hunter. The detailed pattern printing showcases weathering, armor plates, and equipment across the white base color, creating a striking alternative to his iconic green armor. White Mandalorian armor has historical significance in Star Wars lore, often associated with elite warriors and specialized units. This variant may represent Boba Fett during specific missions requiring different camouflage or could depict concept designs from his character development. The intricate printing demonstrates LEGO\'s ability to create visually distinct variants of popular characters. Collectors highly prize this unusual Boba Fett color scheme for its rarity, distinctive appearance, and the mystery surrounding its canonical significance, making it one of the most unique bounty hunter variants in LEGO Star Wars history.',
    description_de: 'Diese einzigartige weiße Boba-Fett-Variante repräsentiert entweder Prototyp-Mandalorianische Rüstung, frühe Karrieredesigns oder spezialisierte Winter-Tarnausrüstung, die vom berühmtesten Kopfgeldjäger der Galaxis verwendet wird. Die detaillierte Musterbedruckung zeigt Verwitterung, Rüstungsplatten und Ausrüstung auf der weißen Grundfarbe und schafft eine auffallende Alternative zu seiner ikonischen grünen Rüstung. Weiße Mandalorianische Rüstung hat historische Bedeutung in der Star-Wars-Überlieferung, oft verbunden mit Elite-Kriegern und spezialisierten Einheiten. Diese Variante könnte Boba Fett während spezifischer Missionen repräsentieren, die andere Tarnung erforderten, oder könnte Konzeptdesigns aus seiner Charakterentwicklung darstellen. Die komplizierte Bedruckung demonstriert LEGOs Fähigkeit, visuell unterschiedliche Varianten beliebter Charaktere zu schaffen. Sammler schätzen dieses ungewöhnliche Boba-Fett-Farbschema sehr für seine Seltenheit, markantes Erscheinungsbild und das Mysterium um seine kanonische Bedeutung, was es zu einer der einzigartigsten Kopfgeldjäger-Varianten in der LEGO-Star-Wars-Geschichte macht.',
    description_fr: 'Cette variante unique de Boba Fett blanc représente soit une armure mandalorienne prototype, des designs de début de carrière ou un équipement de camouflage hivernal spécialisé utilisé par le chasseur de primes le plus célèbre de la galaxie. L\'impression de motif détaillée met en valeur l\'usure, les plaques d\'armure et l\'équipement sur la couleur de base blanche, créant une alternative frappante à son armure verte iconique. L\'armure mandalorienne blanche a une signification historique dans la tradition Star Wars, souvent associée aux guerriers d\'élite et aux unités spécialisées. Cette variante peut représenter Boba Fett pendant des missions spécifiques nécessitant un camouflage différent ou pourrait dépeindre des designs conceptuels de son développement de personnage. L\'impression complexe démontre la capacité de LEGO à créer des variantes visuellement distinctes de personnages populaires. Les collectionneurs apprécient hautement ce schéma de couleurs inhabituel de Boba Fett pour sa rareté, son apparence distinctive et le mystère entourant sa signification canonique, en faisant l\'une des variantes de chasseur de primes les plus uniques dans l\'histoire de LEGO Star Wars.',
    description_es: 'Esta variante única de Boba Fett blanco representa ya sea armadura mandaloriana prototipo, diseños de carrera temprana o equipo de camuflaje invernal especializado usado por el cazarrecompensas más famoso de la galaxia. La impresión de patrón detallado muestra desgaste, placas de armadura y equipo sobre el color base blanco, creando una alternativa llamativa a su icónica armadura verde. La armadura mandaloriana blanca tiene significado histórico en la tradición de Star Wars, a menudo asociada con guerreros de élite y unidades especializadas. Esta variante puede representar a Boba Fett durante misiones específicas que requieren camuflaje diferente o podría representar diseños conceptuales de su desarrollo de personaje. La impresión intrincada demuestra la capacidad de LEGO para crear variantes visualmente distintas de personajes populares. Los coleccionistas valoran altamente este esquema de color inusual de Boba Fett por su rareza, apariencia distintiva y el misterio que rodea su significado canónico, convirtiéndola en una de las variantes de cazarrecompensas más únicas en la historia de LEGO Star Wars.'
  },
  {
    minifigure_no: 'sw0632',
    name: 'Imperial TIE Fighter Pilot - Printed Arms',
    description_en: 'This Imperial TIE Fighter Pilot variant features enhanced detail with printed arms showing the continuation of the flight suit\'s life support systems and equipment connections. TIE pilots were elite Imperial Navy pilots who flew the Empire\'s iconic twin ion engine fighters across the galaxy. The printed arms represent LEGO\'s evolution toward more comprehensive minifigure detailing, extending the black flight suit design beyond just the torso. These pilots underwent intensive training at Imperial academies and were among the few personnel trusted to fly combat spacecraft. The all-black flight suit contained essential life support equipment since TIE fighters lacked environmental controls and shielding. TIE pilots were known for their fearlessness and loyalty to the Empire, often flying suicidal missions without question. Collectors value this printed-arm variant for its enhanced realism, making it ideal for building detailed TIE fighter cockpits and Imperial pilot displays that showcase the technological dependence of these warriors.',
    description_de: 'Diese imperiale TIE-Jäger-Piloten-Variante zeigt verbesserte Details mit bedruckten Armen, die die Fortsetzung der Lebenserhaltungssysteme und Ausrüstungsverbindungen des Fluganzugs zeigen. TIE-Piloten waren Elite-Piloten der imperialen Marine, die die ikonischen Twin-Ionen-Motor-Jäger des Imperiums durch die Galaxis flogen. Die bedruckten Arme repräsentieren LEGOs Entwicklung hin zu umfassenderen Minifiguren-Details und erweitern das Design des schwarzen Fluganzugs über den Torso hinaus. Diese Piloten durchliefen intensive Ausbildung an imperialen Akademien und gehörten zu den wenigen Personen, denen man vertraute, Kampfraumschiffe zu fliegen. Der schwarze Fluganzug enthielt wesentliche Lebenserhaltungsausrüstung, da TIE-Jäger keine Umgebungskontrollen und Schildung hatten. TIE-Piloten waren für ihre Furchtlosigkeit und Loyalität zum Imperium bekannt und flogen oft selbstmörderische Missionen ohne zu zögern. Sammler schätzen diese Variante mit bedruckten Armen für ihren verbesserten Realismus, was sie ideal für den Aufbau detaillierter TIE-Jäger-Cockpits und imperialer Piloten-Displays macht, die die technologische Abhängigkeit dieser Krieger zeigen.',
    description_fr: 'Cette variante de Pilote de Chasseur TIE Impérial présente des détails améliorés avec des bras imprimés montrant la continuation des systèmes de survie et des connexions d\'équipement de la combinaison de vol. Les pilotes TIE étaient des pilotes d\'élite de la Marine Impériale qui pilotaient les chasseurs à moteur ionique jumeau iconiques de l\'Empire à travers la galaxie. Les bras imprimés représentent l\'évolution de LEGO vers des détails de minifigurine plus complets, étendant le design de la combinaison de vol noire au-delà du simple torse. Ces pilotes suivaient un entraînement intensif dans les académies impériales et faisaient partie du peu de personnel à qui on faisait confiance pour piloter des vaisseaux de combat spatiaux. La combinaison de vol entièrement noire contenait un équipement de survie essentiel car les chasseurs TIE manquaient de contrôles environnementaux et de blindage. Les pilotes TIE étaient connus pour leur intrépidité et leur loyauté envers l\'Empire, pilotant souvent des missions suicidaires sans question. Les collectionneurs apprécient cette variante à bras imprimés pour son réalisme amélioré, la rendant idéale pour construire des cockpits de chasseurs TIE détaillés et des displays de pilotes impériaux qui mettent en valeur la dépendance technologique de ces guerriers.',
    description_es: 'Esta variante de Piloto de Caza TIE Imperial presenta detalle mejorado con brazos impresos mostrando la continuación de los sistemas de soporte vital y conexiones de equipo del traje de vuelo. Los pilotos TIE eran pilotos de élite de la Marina Imperial que volaban los icónicos cazas de motor iónico gemelo del Imperio a través de la galaxia. Los brazos impresos representan la evolución de LEGO hacia detalles de minifiguras más completos, extendiendo el diseño del traje de vuelo negro más allá del torso. Estos pilotos se sometían a entrenamiento intensivo en academias imperiales y estaban entre el poco personal en quien se confiaba para volar naves espaciales de combate. El traje de vuelo completamente negro contenía equipo esencial de soporte vital ya que los cazas TIE carecían de controles ambientales y blindaje. Los pilotos TIE eran conocidos por su valentía y lealtad al Imperio, a menudo volando misiones suicidas sin cuestionar. Los coleccionistas valoran esta variante de brazos impresos por su realismo mejorado, haciéndola ideal para construir cabinas de cazas TIE detalladas y exhibiciones de pilotos imperiales que muestran la dependencia tecnológica de estos guerreros.'
  },
  {
    minifigure_no: 'sw0633',
    name: 'Admiral Wullf Yularen - White Uniform, White Combed Hair (Colonel)',
    description_en: 'Admiral Wullf Yularen served as a respected naval officer during the Clone Wars before transitioning to Imperial Security Bureau leadership during the Empire\'s reign. This minifigure features his distinctive white Republic Navy uniform and white combed hair, though labeled as Colonel this represents his Clone Wars service under Anakin Skywalker. Yularen commanded the Resolute, serving as Anakin\'s military advisor and fleet commander during major Clone Wars campaigns. His tactical expertise and by-the-book approach balanced Anakin\'s unconventional strategies. After the Empire\'s rise, Yularen joined the ISB, appearing as the white-uniformed officer in the Death Star conference room briefing in A New Hope. The white uniform signifies high naval rank within Republic forces. Collectors value this figure for its dual-era significance, connection to both Clone Wars and Original Trilogy periods, and representation of career officers who served both the Republic and Empire.',
    description_de: 'Admiral Wullf Yularen diente als respektierter Marineoffizier während der Klonkriege, bevor er während der Herrschaft des Imperiums zur Führung des Kaiserlichen Sicherheitsbüros wechselte. Diese Minifigur zeigt seine markante weiße Uniform der republikanischen Marine und weißes gekämmtes Haar, obwohl als Oberst bezeichnet, repräsentiert dies seinen Klonkriegs-Dienst unter Anakin Skywalker. Yularen befehligte die Resolute und diente als Anakins Militärberater und Flottenkommandeur während wichtiger Klonkriegs-Kampagnen. Seine taktische Expertise und sein buchstabengetreuer Ansatz balancierten Anakins unkonventionelle Strategien aus. Nach dem Aufstieg des Imperiums trat Yularen dem ISB bei und erschien als weiß uniformierter Offizier im Todesstern-Konferenzraum-Briefing in Eine neue Hoffnung. Die weiße Uniform bedeutet hohen Marinerang innerhalb republikanischer Streitkräfte. Sammler schätzen diese Figur für ihre zweizeitige Bedeutung, Verbindung sowohl zu Klonkriegs- als auch Original-Trilogie-Perioden und Darstellung von Karriereoffizieren, die sowohl der Republik als auch dem Imperium dienten.',
    description_fr: 'L\'Amiral Wullf Yularen a servi comme officier naval respecté pendant la Guerre des Clones avant de passer au leadership du Bureau de Sécurité Impérial pendant le règne de l\'Empire. Cette minifigurine présente son uniforme blanc distinctif de la Marine de la République et des cheveux blancs peignés, bien qu\'étiqueté comme Colonel cela représente son service de Guerre des Clones sous Anakin Skywalker. Yularen commandait le Resolute, servant de conseiller militaire d\'Anakin et commandant de flotte pendant les principales campagnes de la Guerre des Clones. Son expertise tactique et son approche selon les règles équilibraient les stratégies non conventionnelles d\'Anakin. Après la montée de l\'Empire, Yularen a rejoint l\'ISB, apparaissant comme l\'officier en uniforme blanc dans la salle de conférence de l\'Étoile de la Mort dans Un Nouvel Espoir. L\'uniforme blanc signifie un rang naval élevé au sein des forces de la République. Les collectionneurs apprécient cette figurine pour sa signification double ère, sa connexion aux périodes de la Guerre des Clones et de la Trilogie Originale, et la représentation d\'officiers de carrière qui ont servi à la fois la République et l\'Empire.',
    description_es: 'El Almirante Wullf Yularen sirvió como oficial naval respetado durante las Guerras Clon antes de transicionar al liderazgo del Buró de Seguridad Imperial durante el reinado del Imperio. Esta minifigura presenta su distintivo uniforme blanco de la Marina de la República y cabello blanco peinado, aunque etiquetado como Coronel esto representa su servicio de Guerras Clon bajo Anakin Skywalker. Yularen comandó el Resolute, sirviendo como asesor militar de Anakin y comandante de flota durante las principales campañas de las Guerras Clon. Su experiencia táctica y enfoque según el libro equilibraban las estrategias no convencionales de Anakin. Después del ascenso del Imperio, Yularen se unió al ISB, apareciendo como el oficial uniformado de blanco en la sala de conferencias de la Estrella de la Muerte en Una Nueva Esperanza. El uniforme blanco significa alto rango naval dentro de las fuerzas de la República. Los coleccionistas valoran esta figura por su significado de doble era, conexión con períodos tanto de Guerras Clon como de Trilogía Original, y representación de oficiales de carrera que sirvieron tanto a la República como al Imperio.'
  },
  {
    minifigure_no: 'sw0634',
    name: 'Emperor Palpatine',
    description_en: 'Emperor Palpatine, also known as Darth Sidious, was the Dark Lord of the Sith who orchestrated the fall of the Republic and ruled the Galactic Empire with absolute power. This minifigure captures his iconic appearance with hooded black robes, pale wrinkled face showing the corruption of the dark side, and yellow Sith eyes. As the master manipulator who executed Order 66 and transformed Anakin into Darth Vader, Palpatine represents ultimate evil in Star Wars. His mastery of Force lightning and dark side powers made him one of the most powerful Sith Lords in galactic history. The Emperor\'s role spans from Senator Palpatine in The Phantom Menace through his defeat at Endor in Return of the Jedi and beyond. Collectors highly value Emperor Palpatine figures for their central importance to Star Wars lore, connection to the saga\'s most pivotal moments, and necessity in Death Star throne room and Imperial displays.',
    description_de: 'Imperator Palpatine, auch bekannt als Darth Sidious, war der Dunkle Lord der Sith, der den Fall der Republik orchestrierte und das Galaktische Imperium mit absoluter Macht regierte. Diese Minifigur erfasst sein ikonisches Erscheinungsbild mit schwarzen Kapuzenroben, blassem faltigem Gesicht, das die Korruption der dunklen Seite zeigt, und gelben Sith-Augen. Als Meistermanipulator, der Order 66 ausführte und Anakin in Darth Vader verwandelte, repräsentiert Palpatine ultimative Bösartigkeit in Star Wars. Seine Beherrschung von Machtblitzen und Kräften der dunklen Seite machte ihn zu einem der mächtigsten Sith-Lords in der galaktischen Geschichte. Die Rolle des Imperators erstreckt sich von Senator Palpatine in Die dunkle Bedrohung über seine Niederlage in Endor in Die Rückkehr der Jedi-Ritter und darüber hinaus. Sammler schätzen Imperator-Palpatine-Figuren sehr für ihre zentrale Bedeutung für die Star-Wars-Überlieferung, Verbindung zu den entscheidendsten Momenten der Saga und Notwendigkeit in Todesstern-Thronsaal- und imperialen Displays.',
    description_fr: 'L\'Empereur Palpatine, également connu sous le nom de Dark Sidious, était le Seigneur Noir des Sith qui a orchestré la chute de la République et gouverné l\'Empire Galactique avec un pouvoir absolu. Cette minifigurine capture son apparence iconique avec des robes noires à capuche, un visage pâle ridé montrant la corruption du côté obscur et des yeux Sith jaunes. En tant que maître manipulateur qui a exécuté l\'Ordre 66 et transformé Anakin en Dark Vador, Palpatine représente le mal ultime dans Star Wars. Sa maîtrise des éclairs de Force et des pouvoirs du côté obscur en faisait l\'un des Seigneurs Sith les plus puissants de l\'histoire galactique. Le rôle de l\'Empereur s\'étend du Sénateur Palpatine dans La Menace Fantôme à sa défaite à Endor dans Le Retour du Jedi et au-delà. Les collectionneurs apprécient hautement les figurines de l\'Empereur Palpatine pour leur importance centrale dans la tradition Star Wars, leur connexion aux moments les plus cruciaux de la saga et leur nécessité dans les displays de la salle du trône de l\'Étoile de la Mort et impériaux.',
    description_es: 'El Emperador Palpatine, también conocido como Darth Sidious, fue el Señor Oscuro de los Sith que orquestó la caída de la República y gobernó el Imperio Galáctico con poder absoluto. Esta minifigura captura su apariencia icónica con túnicas negras con capucha, rostro pálido arrugado mostrando la corrupción del lado oscuro y ojos Sith amarillos. Como el maestro manipulador que ejecutó la Orden 66 y transformó a Anakin en Darth Vader, Palpatine representa el mal definitivo en Star Wars. Su dominio de los rayos de Fuerza y poderes del lado oscuro lo convirtió en uno de los Señores Sith más poderosos de la historia galáctica. El papel del Emperador abarca desde el Senador Palpatine en La Amenaza Fantasma hasta su derrota en Endor en El Retorno del Jedi y más allá. Los coleccionistas valoran altamente las figuras del Emperador Palpatine por su importancia central para la tradición de Star Wars, conexión con los momentos más cruciales de la saga y necesidad en sala del trono de la Estrella de la Muerte y exhibiciones imperiales.'
  }
];

async function saveBatch() {
  console.log('Starting batch save for sw0623-sw0634...');

  for (const minifig of batch) {
    try {
      await prisma.minifigCatalog.update({
        where: { minifigure_no: minifig.minifigure_no },
        data: {
          description_en: minifig.description_en,
          description_de: minifig.description_de,
          description_fr: minifig.description_fr,
          description_es: minifig.description_es,
          description_generated_at: new Date(),
          description_status: 'generated'
        },
      });
      console.log(`✓ Saved ${minifig.minifigure_no}: ${minifig.name}`);
    } catch (error) {
      console.error(`✗ Error saving ${minifig.minifigure_no}:`, error);
    }
  }

  console.log('Batch complete! 12 minifigs saved.');
  await prisma.$disconnect();
}

saveBatch();
